.mo0-vinyl-deck-platter{position:relative;flex:0 0 auto;width:126px;height:126px;border-radius:50%;background:radial-gradient(circle at 50% 45%,#252b3d,#12151f 72%);box-shadow:inset 0 0 0 1px rgba(255,255,255,.08),0 10px 22px rgba(0,0,0,.6)}
.mo0-vinyl-deck-disc{position:absolute;inset:5px;border-radius:50%;overflow:hidden;background:repeating-radial-gradient(circle at 50% 50%,#0a0c11 0 2px,#15181f 2px 3.4px),radial-gradient(circle,#191c25,#05060a);animation:mo0-vinyl-deck-spin 1.85s linear infinite;will-change:transform}
.mo0-vinyl-deck-wedge{position:absolute;inset:0;border-radius:50%;background:conic-gradient(from 0deg,rgba(255,255,255,.16),rgba(255,255,255,0) 22%,rgba(255,255,255,0) 78%,rgba(255,255,255,.09))}
.mo0-vinyl-deck-label{position:absolute;left:50%;top:50%;width:44px;height:44px;margin:-22px 0 0 -22px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:radial-gradient(circle at 32% 28%,#ffd8a2,var(--mo0-vinyl-deck-acc) 55%,#a4501c);box-shadow:0 0 0 1px rgba(0,0,0,.5)}
.mo0-vinyl-deck-ltxt{font-size:8px;letter-spacing:.14em;font-weight:700;color:#3a1a06}
.mo0-vinyl-deck-shine{position:absolute;inset:5px;border-radius:50%;pointer-events:none;background:linear-gradient(122deg,rgba(255,255,255,.14) 0%,rgba(255,255,255,0) 34%,rgba(255,255,255,0) 62%,rgba(255,255,255,.07) 100%);mix-blend-mode:screen}
.mo0-vinyl-deck-spindle{position:absolute;left:50%;top:50%;width:7px;height:7px;margin:-3.5px 0 0 -3.5px;border-radius:50%;background:linear-gradient(160deg,#e8edf8,#78829a);box-shadow:0 0 0 2px rgba(0,0,0,.55)}
.mo0-vinyl-deck-arm{position:absolute;left:132px;top:30px;width:0;height:0;z-index:4}
.mo0-vinyl-deck-pivot{position:absolute;left:-8px;top:-8px;width:16px;height:16px;border-radius:50%;background:linear-gradient(155deg,#d7dded,#666f83);box-shadow:0 3px 8px rgba(0,0,0,.65),inset 0 0 0 1px rgba(255,255,255,.25)}
.mo0-vinyl-deck-tube{position:absolute;right:0;top:-2px;width:66px;height:4px;border-radius:3px;background:linear-gradient(180deg,#eef2fb,#8891a6);box-shadow:0 3px 7px rgba(0,0,0,.5);transform-origin:100% 50%;transform:rotate(19deg);transition:transform 1.15s cubic-bezier(.34,1.45,.5,1)}
.mo0-vinyl-deck-cart{position:absolute;left:-3px;top:-4px;width:14px;height:12px;border-radius:3px;background:linear-gradient(160deg,#464e63,#1d212b);box-shadow:0 2px 5px rgba(0,0,0,.6)}
.mo0-vinyl-deck-info{flex:1 1 auto;min-width:0}
.mo0-vinyl-deck-title{margin:0;font-size:13px;font-weight:650;letter-spacing:.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mo0-vinyl-deck-sub{margin:2px 0 9px;font-size:10.5px;color:#95a0bb;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mo0-vinyl-deck-meter{position:relative;height:4px;border-radius:3px;background:rgba(255,255,255,.09);overflow:hidden}
.mo0-vinyl-deck-fill{position:absolute;inset:0;border-radius:3px;background:linear-gradient(90deg,#ffca7a,var(--mo0-vinyl-deck-acc));transform-origin:0 50%;transform:scaleX(.18)}
.mo0-vinyl-deck-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:11px}
.mo0-vinyl-deck-btn{display:inline-flex;align-items:center;gap:7px;padding:6px 11px 6px 9px;border-radius:999px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.07);color:#eef1f8;font:inherit;font-size:11px;font-weight:600;cursor:pointer;transition:transform .28s cubic-bezier(.34,1.6,.5,1),background .2s ease}
.mo0-vinyl-deck-btn:hover{background:rgba(255,255,255,.13)}
.mo0-vinyl-deck-btn:active{transform:scale(.93)}
.mo0-vinyl-deck-btn:focus-visible{outline:2px solid var(--mo0-vinyl-deck-acc);outline-offset:2px}
.mo0-vinyl-deck-glyph{position:relative;display:block;width:10px;height:11px}
.mo0-vinyl-deck-glyph::before,.mo0-vinyl-deck-glyph::after{content:"";position:absolute;top:0;width:3px;height:11px;border-radius:1px;background:var(--mo0-vinyl-deck-acc);transition:transform .3s cubic-bezier(.34,1.5,.5,1),opacity .2s ease}
.mo0-vinyl-deck-glyph::before{left:0}
.mo0-vinyl-deck-glyph::after{right:0}
.mo0-vinyl-deck-off .mo0-vinyl-deck-glyph::before{transform:scale(.2);opacity:0}
.mo0-vinyl-deck-off .mo0-vinyl-deck-glyph::after{transform-origin:100% 50%;transform:translateX(-1px) scaleX(3.3);clip-path:polygon(0 0,100% 50%,0 100%);border-radius:0}
.mo0-vinyl-deck-off .mo0-vinyl-deck-disc{animation-play-state:paused}
.mo0-vinyl-deck-rpm{font-size:10px;color:#7f8aa5;letter-spacing:.05em}
@keyframes mo0-vinyl-deck-spin{to{transform:rotate(360deg)}}
@media (prefers-reduced-motion:reduce){.mo0-vinyl-deck-disc{animation:none}.mo0-vinyl-deck-tube{transition:none}}

js:
var disc=root.querySelector('.mo0-vinyl-deck-disc');
var tube=root.querySelector('.mo0-vinyl-deck-tube');
var fill=root.querySelector('.mo0-vinyl-deck-fill');
var btn=root.querySelector('.mo0-vinyl-deck-btn');
var txt=root.querySelector('.mo0-vinyl-deck-btxt');
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var PARK=19,A0=2,A1=-22,LEN=214;
var p=0.16,playing=true,shown=999,raf=0,last=0;
function arm(){
  var a=playing?A0+(A1-A0)*p:PARK;
  if(Math.abs(a-shown)<0.12)return;
  shown=a;tube.style.transform='rotate('+a.toFixed(2)+'deg)';
}
function paint(){fill.style.transform='scaleX('+(0.02+p*0.98).toFixed(4)+')';arm();}
function frame(t){
  if(!last)last=t;
  var dt=Math.min(0.05,(t-last)/1000);last=t;
  if(playing){p+=dt/LEN;if(p>=1){p=0;shown=999;}}
  paint();
  raf=requestAnimationFrame(frame);
}
function setPlay(v){
  playing=v;shown=999;
  root.classList.toggle('mo0-vinyl-deck-off',!v);
  btn.setAttribute('aria-pressed',v?'true':'false');
  btn.setAttribute('aria-label',v?'Pause':'Play');
  txt.textContent=v?'Pause':'Play';
  arm();
}
btn.addEventListener('click',function(){setPlay(!playing);});
if(reduce){paint();disc.style.transform='rotate(24deg)';}
else{paint();raf=requestAnimationFrame(frame);}

