.mo0-cassette-reels-g{display:block;background:#cfd8ec}
.mo0-cassette-reels-on .mo0-cassette-reels-g{background:var(--mo0-cassette-reels-acc)}
.mo0-cassette-reels-g-play{width:9px;height:10px;clip-path:polygon(0 0,100% 50%,0 100%)}
.mo0-cassette-reels-playing .mo0-cassette-reels-g-play{width:3.5px;height:10px;clip-path:none;box-shadow:6px 0 0 var(--mo0-cassette-reels-acc)}
.mo0-cassette-reels-g-ff{width:11px;height:9px;clip-path:polygon(0 0,50% 50%,0 100%,50% 100%,100% 50%,50% 0)}
