.mo0-cassette-reels-counter{margin-left:auto;display:flex;gap:2px;padding:3px 4px;border-radius:4px;background:#0a0d14;box-shadow:inset 0 1px 3px rgba(0,0,0,.8)}
.mo0-cassette-reels-d{display:block;width:11px;text-align:center;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:11px;line-height:14px;color:#c9d4ea}
.mo0-cassette-reels-d4{color:var(--mo0-cassette-reels-acc)}
