@keyframes mo0-cassette-reels-pop{0%{transform:translateY(-7px) scale(.8);opacity:.2}100%{transform:none;opacity:1}}
@keyframes mo0-cassette-reels-sweep{0%,55%{transform:translateX(-70%)}100%{transform:translateX(70%)}}
@media (prefers-reduced-motion:reduce){.mo0-cassette-reels-glass{animation:none;opacity:.35}.mo0-cassette-reels-pop{animation:none}}

js:
var svg=root.querySelector('.mo0-cassette-reels-svg');
var packs=root.querySelectorAll('.mo0-cassette-reels-pack');
var rings=root.querySelectorAll('.mo0-cassette-reels-ring');
var band=root.querySelector('.mo0-cassette-reels-band');
var gA=root.querySelector('.mo0-cassette-reels-hubA');
var gB=root.querySelector('.mo0-cassette-reels-hubB');
var digits=root.querySelectorAll('.mo0-cassette-reels-d');
var keys=root.querySelectorAll('.mo0-cassette-reels-key');
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var RH=9,RM=25,p=0.34,mode='play',aA=0,aB=0,last=0,shownCount=-1;
function radius(f){return Math.sqrt(RH*RH+(RM*RM-RH*RH)*Math.max(0,Math.min(1,f)));}
function count(){
  var v=Math.round(p*999),s=('0000'+v).slice(-4);
  if(v===shownCount)return;shownCount=v;
  for(var i=0;i<digits.length;i++){
    var ch=s.charAt(i);
    if(digits[i].textContent!==ch){
      digits[i].textContent=ch;
      if(!reduce){digits[i].classList.remove('mo0-cassette-reels-pop');void digits[i].offsetWidth;digits[i].classList.add('mo0-cassette-reels-pop');}
    }
  }
}
function draw(t){
  var rs=radius(1-p),rt=radius(p);
  packs[0].setAttribute('r',rs.toFixed(2));
  packs[1].setAttribute('r',rt.toFixed(2));
  rings[0].setAttribute('r',Math.max(RH+2,rs-3).toFixed(2));
  rings[1].setAttribute('r',Math.max(RH+2,rt-3).toFixed(2));
  var flut=reduce?0:Math.sin(t/260)*0.35+Math.sin(t/97)*0.15;
  band.setAttribute('y',(29.4+flut).toFixed(2));
  gA.setAttribute('transform','rotate('+aA.toFixed(2)+' 66 31)');
  gB.setAttribute('transform','rotate('+aB.toFixed(2)+' 178 31)');
  count();
}
function frame(t){
  if(!last)last=t;
  var dt=Math.min(0.05,(t-last)/1000);last=t;
  var dir=mode==='rew'?-1:1;
  var speed=mode==='play'?1:(mode==='pause'?0:6.5);
  if(speed){
    p+=dir*speed*dt/150;
    if(p>1){p=1;setMode('pause');}
    if(p<0){p=0;setMode('pause');}
    var v=speed*260;
    aA+=dir*v*dt/radius(1-p);
    aB+=dir*v*dt/radius(p);
  }
  draw(t);
  requestAnimationFrame(frame);
}
function setMode(m){
  mode=m;
  root.classList.toggle('mo0-cassette-reels-playing',m==='play');
  for(var i=0;i<keys.length;i++){
    var k=keys[i].getAttribute('data-mo0-cassette-reels');
    var on=(k===m)||(k==='play'&&m==='play');
    keys[i].classList.toggle('mo0-cassette-reels-on',on);
    keys[i].setAttribute('aria-pressed',on?'true':'false');
  }
}
for(var i=0;i<keys.length;i++){
  keys[i].addEventListener('click',function(e){
    var k=e.currentTarget.getAttribute('data-mo0-cassette-reels');
    if(k==='play')setMode(mode==='play'?'pause':'play');
    else setMode(mode===k?'play':k);
  });
}
setMode('play');
if(reduce){draw(0);}else{requestAnimationFrame(frame);}

