js:
var tray=root.querySelector('.mo0-cd-transport-tray');
var disc=root.querySelector('.mo0-cd-transport-disc');
var rail=root.querySelector('.mo0-cd-transport-rail');
var sled=root.querySelector('.mo0-cd-transport-sled');
var stat=root.querySelector('.mo0-cd-transport-stat');
var time=root.querySelector('.mo0-cd-transport-time');
var playBtn=root.querySelector('.mo0-cd-transport-key-p');
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var DUR=252,secs=41,ang=0,vel=0,tgt=1,state='play',last=0,timers=[];
function clearT(){for(var i=0;i<timers.length;i++)clearTimeout(timers[i]);timers=[];}
function seq(steps){clearT();var acc=0;steps.forEach(function(s){acc+=s[0];timers.push(setTimeout(s[1],acc));});}
function setStat(s){stat.textContent=s;if(reduce)return;stat.classList.remove('mo0-cd-transport-flash');void stat.offsetWidth;stat.classList.add('mo0-cd-transport-flash');}
function sledTo(f){var w=Math.max(0,rail.clientWidth-22);sled.style.transform='translate3d('+(w*Math.max(0,Math.min(1,f))).toFixed(1)+'px,0,0)';}
function clock(){var s=Math.floor(secs),m=Math.floor(s/60);time.textContent=('0'+m).slice(-2)+':'+('0'+(s%60)).slice(-2);}
