var back=root.querySelector('.mo0-cover-flip-back');
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var open=false;
function sync(){
  root.classList.toggle('mo0-cover-flip-open',open);
  for(var i=0;i<btns.length;i++)btns[i].setAttribute('aria-expanded',open?'true':'false');
  btns[0].tabIndex=open?-1:0;btns[1].tabIndex=open?0:-1;
  back.setAttribute('aria-hidden',open?'false':'true');
}
for(var i=0;i<btns.length;i++){
  btns[i].addEventListener('click',function(e){
    var kb=e.detail===0;
    open=!open;sync();
    if(!kb)return;
    var next=open?btns[1]:btns[0];
    setTimeout(function(){try{next.focus({preventScroll:true});}catch(err){}},520);
  });
}
if(!reduce){
  root.addEventListener('pointermove',function(e){
    var r=root.getBoundingClientRect();
    var x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;
    tilt.style.transform='rotateY('+(x*13).toFixed(2)+'deg) rotateX('+(-y*11).toFixed(2)+'deg)';
  });
