var fill=root.querySelector('.mo0-nowplay-bar-fill');
var dot=root.querySelector('.mo0-nowplay-bar-dot');
var prog=root.querySelector('.mo0-nowplay-bar-prog');
var cur=root.querySelector('.mo0-nowplay-bar-cur');
var rem=root.querySelector('.mo0-nowplay-bar-rem');
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
