  var room=mask.clientWidth;
  if(one>room-2&&!reduce){
    root.classList.remove('mo0-nowplay-bar-still');
    var shift=one+38;
    track.style.setProperty('--mo0-nowplay-bar-shift',shift.toFixed(1)+'px');
    root.style.setProperty('--mo0-nowplay-bar-dur',(shift/34).toFixed(2)+'s');
  }else{
    root.classList.add('mo0-nowplay-bar-still');
  }
