  var d=songs[idx][2];
  fill.style.transform='scaleX('+p.toFixed(4)+')';
  dot.style.transform='translate3d('+(p*w).toFixed(1)+'px,0,0)';
  cur.textContent=fmt(p*d);
  rem.textContent='-'+fmt(d-p*d);
}
function load(i){
  idx=(i+songs.length)%songs.length;p=0;
  tt[0].textContent=songs[idx][0];tt[1].textContent=songs[idx][0];
  artist.textContent=songs[idx][1];
  measure();paint();
