  play(t2,soft,function(v){return{opacity:String(Math.min(1,v*2.6)),transform:'translate3d('+((1-v)*26).toFixed(2)+'px,0,0)'};},215);
  play(bar,soft,function(v){return{opacity:String(Math.min(1,v*3)),transform:'scaleX('+(.2+.8*v).toFixed(4)+')'};},255);
  var a=play(row,pop,function(v){return{opacity:String(Math.min(1,v*2.6)),transform:'translate3d(0,'+((1-v)*18).toFixed(2)+'px,0)'};},290);
