var list=root.querySelector('.mo0-queue-flip-list');
var shuf=root.querySelector('.mo0-queue-flip-shuf');
var live=root.querySelector('.mo0-queue-flip-live');
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var timer=0;
function rows(){return Array.prototype.slice.call(list.children);}
function mark(){
  rows().forEach(function(r,i){r.classList.toggle('mo0-queue-flip-now',i===0);});
}
function flip(mutate){
  var before=rows();
  before.forEach(function(r){r.__mo0y=r.getBoundingClientRect().top;});
  mutate();
  var after=rows();
  after.forEach(function(r){
    var d=r.__mo0y-r.getBoundingClientRect().top;
    r.style.transition='none';
    r.style.transform='translate3d(0,'+d.toFixed(1)+'px,0)';
  });
  void list.offsetWidth;
  after.forEach(function(r,i){
    r.style.transition='transform .68s cubic-bezier(.22,1.28,.36,1) '+(i*38)+'ms';
    r.style.transform='translate3d(0,0,0)';
  });
  mark();
}
function advance(){
  var t=list.firstElementChild;
  if(!t)return;
  if(reduce){list.appendChild(t);mark();return;}
  flip(function(){list.appendChild(t);});
  live.textContent='Now playing '+(list.firstElementChild.querySelector('.mo0-queue-flip-tt').textContent);
  restart();
}
function shuffle(){
  var r=rows(),tail=r.slice(1);
  for(var i=tail.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var tmp=tail[i];tail[i]=tail[j];tail[j]=tmp;}
  if(reduce){tail.forEach(function(n){list.appendChild(n);});mark();return;}
  flip(function(){tail.forEach(function(n){list.appendChild(n);});});
  live.textContent='Queue shuffled';
}
function up(row){
  var prev=row.previousElementSibling;
  if(!prev)return;
  if(reduce){list.insertBefore(row,prev);mark();return;}
  flip(function(){list.insertBefore(row,prev);});
  live.textContent=row.querySelector('.mo0-queue-flip-tt').textContent+' moved up';
  restart();
}
function restart(){
  clearInterval(timer);
  if(reduce)return;
  timer=setInterval(advance,6600);
}
root.addEventListener('click',function(e){
  var b=e.target.closest?e.target.closest('.mo0-queue-flip-up'):null;
  if(b){up(b.parentNode);return;}
  if(e.target.closest&&e.target.closest('.mo0-queue-flip-shuf'))shuffle();
});
mark();restart();

