var stage=root.querySelector('.mo0-scrub-head-stage');
var cv=root.querySelector('.mo0-scrub-head-cv');
var knob=root.querySelector('.mo0-scrub-head-knob');
var range=root.querySelector('.mo0-scrub-head-range');
var cur=root.querySelector('.mo0-scrub-head-cur');
var bufTxt=root.querySelector('.mo0-scrub-head-buf');
var ctx=cv.getContext('2d');
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var DUR=252,p=.24,buf=.46,W=280,H=62,amps=[],BW=3,GAP=2,x=0,vx=0,grab=0,scale=1,last=0;
function rnd(i){var s=Math.sin(i*127.1+11.7)*43758.5453;return s-Math.floor(s);}
function build(){
  var n=Math.max(8,Math.floor(W/(BW+GAP)));
  amps=[];
  for(var i=0;i<n;i++){
    var env=.32+.68*Math.abs(Math.sin(i*.085+.6))*Math.abs(Math.sin(i*.021+1.9));
    amps.push(Math.min(1,.18+env*(.55+.45*rnd(i))));
  }
}
function size(){
  var r=stage.getBoundingClientRect();
  if(!r.width)return;
  W=r.width;H=r.height;
  var d=Math.min(2,window.devicePixelRatio||1);
  cv.width=Math.round(W*d);cv.height=Math.round(H*d);
  ctx.setTransform(d,0,0,d,0,0);
  build();
}
function fmt(s){s=Math.max(0,Math.floor(s));return Math.floor(s/60)+':'+('0'+(s%60)).slice(-2);}
function draw(t){
  ctx.clearRect(0,0,W,H);
  var n=amps.length,cy=H/2,step=BW+GAP,head=p*(W-12)+6;
  for(var i=0;i<n;i++){
    var bx=i*step+GAP/2,c=bx+BW/2,f=c/W;
    var wob=reduce?1:1+.16*Math.sin(t*.0026+i*.42);
    var near=Math.max(0,1-Math.abs(c-head)/26);
    var h=Math.max(2,amps[i]*(H-10)*wob*(1+near*.5));
    if(f<=p){
      var g=reduce?1:.78+.22*Math.sin(t*.004-i*.3);
      ctx.fillStyle='rgba(255,107,139,'+(0.55+0.45*g).toFixed(3)+')';
    }else if(f<=buf){
      ctx.fillStyle='rgba(196,208,232,0.34)';
    }else{
      ctx.fillStyle='rgba(150,164,196,0.16)';
    }
    ctx.fillRect(bx,cy-h/2,BW,h);
  }
  var bx2=buf*(W-12)+6;
  var sh=reduce?.5:.35+.35*Math.sin(t*.005);
  ctx.fillStyle='rgba(220,232,255,'+sh.toFixed(3)+')';
  ctx.fillRect(bx2-1,4,2,H-8);
}
function knobPaint(){
  knob.style.transform='translate3d('+x.toFixed(2)+'px,0,0) scaleX('+scale.toFixed(3)+') scaleY('+(1+(scale-1)*.35).toFixed(3)+')';
}
function labels(){
  cur.textContent=fmt(p*DUR);
  bufTxt.textContent='buffered '+Math.round(buf*100)+'%';
  range.setAttribute('aria-valuetext',fmt(p*DUR)+' of '+fmt(DUR));
}
function frame(t){
  if(!last)last=t;
  var dt=Math.min(.05,(t-last)/1000);last=t;
  if(!grab){p+=dt/DUR;if(p>1)p=0;range.value=String(Math.round(p*1000));}
  var tgt=Math.min(1,p+.22);
  buf+=(tgt-buf)*Math.min(1,dt*.9);
  if(buf<p)buf=p;if(buf>1)buf=1;
  var tx=p*(W-12),k=grab?420:260,c=grab?32:22;
  var a=-k*(x-tx)-c*vx;vx+=a*dt;x+=vx*dt;
  scale+=((grab?1.35:1)-scale)*Math.min(1,dt*12);
  knobPaint();draw(t);labels();
  requestAnimationFrame(frame);
}
range.addEventListener('input',function(){
  p=Number(range.value)/1000;
  if(buf<p)buf=p;
  labels();
  if(reduce){x=p*(W-12);knobPaint();draw(0);}
});
range.addEventListener('pointerdown',function(){grab=1;});
window.addEventListener('pointerup',function(){grab=0;});
range.addEventListener('keydown',function(){grab=1;});
range.addEventListener('keyup',function(){grab=0;});
range.addEventListener('blur',function(){grab=0;});
